import {api,token,personal,el,button,message,confirmAction} from './common.js';
document.querySelector('#back').href=personal('/');const container=document.querySelector('#gifts'),status=document.querySelector('#gift-status');const labels={available:'Disponível',reserved:'Reservado',purchased:'Comprado'};
let loading=false;
async function load(){if(loading||document.querySelector('dialog[open]'))return;loading=true;try{const {gifts}=await api('/api/gifts');status.textContent=token?'Reserve um presente para o guardar para si. Depois de comprar, confirme aqui.':'Pode consultar a lista. Para reservar, abra esta página através do seu convite pessoal.';container.replaceChildren();for(const gift of gifts){const card=el('article',undefined,'card');card.append(el('h2',gift.name),el('p',gift.description),el('span',labels[gift.status]+(gift.mine?' · A sua escolha':''),'tag '+gift.status));const actions=el('div',undefined,'actions');async function action(a){if(a==='purchased'&&!await confirmAction('Já comprou este presente? A confirmação mantém o presente indisponível para os outros convidados.'))return;if(a==='release'&&!await confirmAction('Libertar a reserva para outro convidado?'))return;try{await api('/api/gifts/'+encodeURIComponent(gift.id),{method:'POST',body:{action:a}});await message(a==='reserve'?'Presente reservado para si.':a==='purchased'?'Compra confirmada. Obrigado pelo carinho!':'Reserva libertada.')}finally{await load()}}
if(gift.status==='available'&&token)actions.append(button('Reservar',()=>action('reserve')));if(gift.mine&&gift.status==='reserved')actions.append(button('Já comprei',()=>action('purchased')),button('Libertar reserva',()=>action('release'),'secondary'));if(gift.mine&&gift.status==='purchased')card.append(el('p','Obrigado! A compra deste presente já está confirmada.'));card.append(actions);container.append(card)}}catch(e){status.textContent=e.message}finally{loading=false}}
load();setInterval(load,15000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)load()});
